CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;
CREATE TABLE public.slack_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, error text);
GRANT ALL ON public.slack_notifications TO service_role;
REVOKE ALL ON public.slack_notifications FROM anon, authenticated;
ALTER TABLE public.slack_notifications ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.dispatch_slack_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN PERFORM net.http_post(url := 'https://zpslppxkrwjxsfotypdp.supabase.co/functions/v1/slack-notify', headers := '{"Content-Type":"application/json"}'::jsonb, body := jsonb_build_object('event_id', NEW.id)); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.dispatch_slack_notification() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER dispatch_slack_notification AFTER INSERT ON public.slack_notifications FOR EACH ROW EXECUTE FUNCTION public.dispatch_slack_notification();
CREATE OR REPLACE FUNCTION public.queue_quote_slack() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN INSERT INTO public.slack_notifications(kind,message) VALUES ('quote', format('New %s quote | %s | %s | Company: %s | Phone: %s | Quantity: %s | Belt width: %s | Details: %s | Estimated total: %s | Review: https://hinjd-ecosystem-hub.lovable.app/crm/usage', NEW.product, NEW.name, NEW.email, coalesce(NEW.company,''),coalesce(NEW.phone,''),coalesce(NEW.quantity::text,''),coalesce(NEW.belt_width,''),left(coalesce(NEW.message,''),2000),coalesce(NEW.estimated_total::text,'Not priced'))); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.queue_quote_slack() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER queue_quote_slack AFTER INSERT ON public.quote_requests FOR EACH ROW EXECUTE FUNCTION public.queue_quote_slack();
CREATE OR REPLACE FUNCTION public.queue_equipment_slack() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE metric text; limit_value numeric; reading numeric; previous numeric; new_data jsonb; old_data jsonb; notes text := ''; BEGIN new_data := coalesce(NEW.telemetry,'{}'::jsonb) || jsonb_build_object('hours_since_service', coalesce(NEW.telemetry->'hours_since_service',to_jsonb(NEW.runtime_hours))); old_data := CASE WHEN TG_OP='UPDATE' THEN coalesce(OLD.telemetry,'{}'::jsonb) || jsonb_build_object('hours_since_service',coalesce(OLD.telemetry->'hours_since_service',to_jsonb(OLD.runtime_hours))) ELSE '{}'::jsonb END; FOR metric,limit_value IN SELECT * FROM (VALUES ('hours_since_service',500),('temp_f',220),('pressure_psi',3000),('downtime_hours',8)) AS limits(metric,lim) LOOP reading := CASE WHEN jsonb_typeof(new_data->metric)='number' THEN (new_data->>metric)::numeric END; previous := CASE WHEN jsonb_typeof(old_data->metric)='number' THEN (old_data->>metric)::numeric END; IF reading > limit_value AND (previous IS NULL OR previous <= limit_value) THEN notes := notes || format('%s: %s (limit %s); ',metric,reading,limit_value); END IF; END LOOP; IF notes <> '' THEN INSERT INTO public.slack_notifications(kind,message) VALUES ('fleet_alert',format('Fleet threshold alert | %s | %s | %s | %s | Work orders: https://hinjd-ecosystem-hub.lovable.app/app/equipment',NEW.node_id,coalesce(NEW.equipment_type,''),coalesce(NEW.model,''),notes)); END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.queue_equipment_slack() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER queue_equipment_slack AFTER INSERT OR UPDATE OF telemetry, runtime_hours ON public.equipment_master FOR EACH ROW EXECUTE FUNCTION public.queue_equipment_slack();